  (8052, 2201, '{5222,5224,5249,5273,5377,8,1115,1251,1288,1580,1605,1606,1629,1725,1802,1858,1859,2070,2071,2125,2127,2186,2211,2271,2358,2430,2433,2552,2553,2693,2711,4023,4915,5991,6026}'::bigint[], '{}'::bigint[]),
